
local qjog=[==[]==]
local qtopb=
(function(...)
local rkh={24,127,98,177,22,56,174,10,196,126,2,172,66,174,141,43,246,49,9,125,0,2,167,191}
local bpry=bit32 or bit
local kg=bpry.bxor
for yrh=1,#rkh do rkh[yrh]=kg(rkh[yrh],(132*yrh+204)%256) end
local hz="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local vn={}
for toog=1,#hz do vn[hz:byte(toog)]=toog-1 end
local function pbr(str)
  local R={} local acc,nb=0,0
  for exqhn=1,#str do
    local v=vn[str:byte(exqhn)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function ft(key,data)
  local S={} for xnrwt=0,255 do S[xnrwt]=xnrwt end
  local j=0
  for bn=0,255 do
    j=(j+S[bn]+key[(bn%#key)+1])%256
    S[bn],S[j]=S[j],S[bn]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(kg(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=ft(rkh,pbr(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local azk=nf()
return function(big) return azk(big) end
end)(...)

return qtopb(qjog)
